import React, {Component, useState} from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from 'axios';

function Order(){
    const [order, setOrder] = useState([]);

    const [newOrder, setNewOrder] = useState({
        name: '',
        position: '',
        room: '',
        email: '',
        note: '',
        pwd: '',
    });

    const [count, setCount] = useState(0);
    const navigate = useNavigate();
    // send cookie with http request
    axios.defaults.withCredentials = true;

    const handleSubmit = (e) => {
        e.preventDefault();

        console.log("Data send is:");
        console.log(order);

        if (order.length === 0){
            alert("Gửi email lỗi! Hãy nhập thông tin về order");
        }
        else {
            for (let i = 0; i < order.length; i++) {
                console.log("Send email request");
                setCount(prevCount => {
                    const newCount = prevCount + 1;
                    console.log("Current count:", newCount); // Log biến count khi nút được nhấn
                    return newCount;
                  });

                // axios.post('http://localhost:8081/order', order[i])
                // .then(res => {
                //     if(res.data.Status === "Success") {
                //         // tang bien dem
                //         setCount(count + 1);
                //         console.log("Send email successfully time", count);
                //     }

                //     else{
                //         alert(res.data.Error);
                //     }
                //     //console.log(res)
                // })

                // .then(err => console.log(err));
            }

            if (count === order.length){
                // reset order and count
                setOrder([]);
                setCount(0);
                // navigate to map
                navigate('/map');
            }
            else{
                setOrder([]);
                setCount(0);
                alert("Gửi email lỗi!!!!!")
            }
        }

    }

    const handleAddOrder = (e) => {
        e.preventDefault();

        if (order.length < 3){
            if (newOrder.name && newOrder.position && newOrder.room && newOrder.email && newOrder.note && newOrder.pwd) {
                if (newOrder.position !== '1' && newOrder.position !== '2' && newOrder.position !== '3'){
                    alert("Hay nhap vi tri Locker la 1, 2 hoặc 3")

                }
                else{
                    if (newOrder.room !== '1' && newOrder.room !== '2' && newOrder.room !== '3'){
                        alert("Hay nhap So phong la 1 2 3")
                    }
                    else{
                        setOrder([
                            ...order,
                            {
                            name: newOrder.name,
                            position: newOrder.position,
                            room: newOrder.room,
                            email: newOrder.email,
                            note: newOrder.note,
                            pwd: newOrder.pwd,
                            }
                        ]);
                        setNewOrder({ name: "", position: "", room: "", email: "", note: "", pwd:"" }); // Reset form sau khi thêm
                    }
                }
            }
            else{
                alert("Thông tin bị thiếu hãy nhập đủ thông tin! Hãy nhập đầy đủ thông tin");

            }
        }

        else{
            alert("Hệ thống cho phép tạo 3 lệnh tối đa");
        }
    }

    return(
        <div className="d-flex justify-content-center align-items-center no-bg vh-1">
            <div className=" bg-white p-3 rounded w-100">
                <h2>Order</h2>

                <form>
                    <div className="mb-3">
                        <label htmlFor="name"><strong>Document Name</strong></label>
                        <input type="text" placeholder="Enter Document Name" 
                        name="name"
                        value={newOrder.name}
                        onChange={(e) => setNewOrder({ ...newOrder, name: e.target.value })} 
                        className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="name"><strong>Locker Position</strong></label>
                        <input type="text" placeholder="Enter position of locker" 
                        name="position"
                        value={newOrder.position}
                        onChange={(e) => setNewOrder({ ...newOrder, position: e.target.value })} 
                        className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="name"><strong>Room</strong></label>
                        <input type="text" placeholder="Enter room number" 
                        name="room"
                        value={newOrder.room}
                        onChange={(e) => setNewOrder({ ...newOrder, room: e.target.value })} 
                        className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="email"><strong>Email</strong></label>
                        <input type="email" placeholder="Enter Email" 
                        name="email"
                        value={newOrder.email}
                        onChange={(e) => setNewOrder({ ...newOrder, email: e.target.value })} 
                        className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="email"><strong>Note</strong></label>
                        <input type="text" placeholder="Enter description" 
                        name="note"
                        value={newOrder.note}
                        onChange={(e) => setNewOrder({ ...newOrder, note: e.target.value })} 
                        className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="password"><strong>Password</strong></label>
                        <input type="text" placeholder="Enter Password" 
                        name="pwd"
                        value={newOrder.pwd}
                        onChange={(e) => setNewOrder({ ...newOrder, pwd: e.target.value })}
                        className="form-control rounded-0"/>
                    </div>

                    <div>
                        <button className="btn btn-success w-50 rounded-0" style={{ border: '5px solid white', padding: '10px 20px', borderRadius: '5px' }} onClick={handleAddOrder}>Add</button>
                        <button className="btn btn-success w-50 rounded-0" style={{ border: '5px solid white', padding: '10px 20px', borderRadius: '5px' }} onClick={handleSubmit}>Submit</button>
                    </div>
                </form>
            </div>
        </div>
    )
}

export default Order;
